<?php
declare(strict_types=1);
session_start();
$root=dirname(__DIR__,3);$cfg=require $root.'/config.php';date_default_timezone_set($cfg['timezone']??'America/Argentina/Buenos_Aires');
if(empty($_SESSION['user'])){header('Location:index.php');exit;}
$db=new PDO('mysql:host='.$cfg['db_host'].';dbname='.$cfg['db_name'].';charset=utf8mb4',$cfg['db_user'],$cfg['db_pass'],[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION,PDO::ATTR_DEFAULT_FETCH_MODE=>PDO::FETCH_ASSOC]);
require_once $root.'/app/Core/UnifiedSidebar.php';
function me($v):string{return htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');}
function myTechView():bool{if(($_SESSION['user']['role']??'')==='admin')return true;$p=$_SESSION['user']['permissions']??[];return !empty($p['technical_projects']['view'])||!empty($p['technical_projects']['manage']);}
if(!myTechView()){http_response_code(403);exit('No tenés permiso para acceder a Mi jornada.');}
$uid=(int)($_SESSION['user']['id']??0);$today=date('Y-m-d');$selected=$_GET['date']??$today;if(!preg_match('/^\d{4}-\d{2}-\d{2}$/',$selected))$selected=$today;
$dayStmt=$db->prepare("SELECT e.*,p.project_number,p.name project_name,p.technical_status,c.business_name,c.city,c.province,pp.business_name partner_name,(SELECT GROUP_CONCAT(u2.name ORDER BY u2.name SEPARATOR ', ') FROM technical_schedule_users tsu2 JOIN users u2 ON u2.id=tsu2.user_id WHERE tsu2.event_id=e.id) team_names FROM technical_schedule_events e JOIN technical_schedule_users tsu ON tsu.event_id=e.id AND tsu.user_id=? JOIN projects p ON p.id=e.project_id JOIN clients c ON c.id=p.client_id LEFT JOIN project_partners pp ON pp.id=p.partner_id WHERE e.work_date=? AND e.status<>'cancelado' ORDER BY COALESCE(e.start_time,'00:00:00'),e.id");$dayStmt->execute([$uid,$selected]);$items=$dayStmt->fetchAll();
$nextStmt=$db->prepare("SELECT e.work_date,e.start_time,e.end_time,e.title,p.id project_id,p.project_number,p.name project_name FROM technical_schedule_events e JOIN technical_schedule_users tsu ON tsu.event_id=e.id AND tsu.user_id=? JOIN projects p ON p.id=e.project_id WHERE e.work_date>? AND e.status='planificado' ORDER BY e.work_date,COALESCE(e.start_time,'00:00:00'),e.id LIMIT 5");$nextStmt->execute([$uid,$selected]);$next=$nextStmt->fetchAll();
$prev=(new DateTimeImmutable($selected))->modify('-1 day')->format('Y-m-d');$tom=(new DateTimeImmutable($selected))->modify('+1 day')->format('Y-m-d');$names=['Sun'=>'Domingo','Mon'=>'Lunes','Tue'=>'Martes','Wed'=>'Miércoles','Thu'=>'Jueves','Fri'=>'Viernes','Sat'=>'Sábado'];$dobj=new DateTimeImmutable($selected);$dayLabel=($names[$dobj->format('D')]??'').', '.$dobj->format('d/m/Y');
?><!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1,viewport-fit=cover"><title>Mi jornada · Punto ERP</title><style><?=erpSidebarCss()?>body{margin:0;background:var(--bg);color:var(--ink);font:15px/1.45 system-ui,-apple-system,Segoe UI,sans-serif}.main{margin-left:var(--sidebar);padding:28px 4%;max-width:1100px}.hero{background:linear-gradient(135deg,#171b20,#2a3139);color:#fff;border-radius:18px;padding:24px;margin-bottom:18px}.hero small{color:#b7c0ca}.hero h1{margin:4px 0 0;font-size:30px}.navday{display:flex;gap:8px;flex-wrap:wrap;margin:14px 0 22px}.btn{display:inline-flex;align-items:center;justify-content:center;gap:7px;border:0;border-radius:10px;padding:11px 15px;background:var(--o);color:#fff;text-decoration:none;font-weight:750;cursor:pointer}.btn.light{background:#fff;color:var(--ink);border:1px solid var(--line)}.job{background:#fff;border:1px solid var(--line);border-radius:16px;padding:20px;margin-bottom:14px;box-shadow:0 4px 16px #00000008}.time{display:inline-block;padding:6px 10px;border-radius:999px;background:#fff1e8;color:#b84d00;font-weight:800}.status{display:inline-block;padding:5px 9px;border-radius:999px;background:#edf0f3;font-size:12px}.job h2{margin:12px 0 5px;font-size:23px}.muted{color:var(--muted)}.meta{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:10px;margin:15px 0}.meta div{padding:11px;border-radius:10px;background:#f6f7f8}.actions{display:flex;gap:9px;flex-wrap:wrap;margin-top:15px}.empty{background:#fff;border:1px dashed #cbd1d7;border-radius:16px;padding:32px;text-align:center}.upcoming{background:#fff;border:1px solid var(--line);border-radius:16px;padding:20px;margin-top:18px}.upcoming-row{display:grid;grid-template-columns:95px 1fr auto;gap:12px;align-items:center;padding:11px 0;border-bottom:1px solid var(--line)}.upcoming-row:last-child{border-bottom:0}@media(max-width:900px){.main{margin-left:0;padding:16px 12px 90px}.hero{padding:20px;border-radius:15px}.hero h1{font-size:26px}.meta{grid-template-columns:1fr}.actions .btn{flex:1}.upcoming-row{grid-template-columns:82px 1fr}.upcoming-row .btn{grid-column:1/-1}.sidebar{z-index:100}.navday .btn{flex:1;min-width:90px}}</style></head><body><?php erpSidebar('my_day');?><main class="main"><section class="hero"><small><?=me($_SESSION['user']['profile_name']??'Técnica')?></small><h1>Hola, <?=me($_SESSION['user']['name']??'')?></h1><div style="margin-top:8px"><?=me($dayLabel)?></div></section><div class="navday"><a class="btn light" href="?a=my_day&date=<?=$prev?>">← Día anterior</a><a class="btn light" href="?a=my_day&date=<?=$today?>">Hoy</a><a class="btn light" href="?a=my_day&date=<?=$tom?>">Día siguiente →</a></div><?php if(!$items):?><div class="empty"><h2>No tenés trabajos asignados para este día</h2><p class="muted">Cuando el responsable técnico te asigne una jornada, va a aparecer acá.</p></div><?php else:foreach($items as $it):$from=$it['start_time']?substr($it['start_time'],0,5):null;$to=$it['end_time']?substr($it['end_time'],0,5):null;$time=$from?($to?$from.' – '.$to:$from):'Horario a definir';?><article class="job"><span class="time"><?=me($time)?></span> <span class="status"><?=me(ucfirst($it['status']))?></span><h2><?=me($it['project_number'])?> · <?=me($it['project_name'])?></h2><div class="muted"><?=me($it['business_name'])?></div><div class="meta"><div><b>Trabajo previsto</b><br><?=me($it['title'])?></div><div><b>Ubicación</b><br><?=me(trim(($it['city']??'').(($it['province']??'')?', '.$it['province']:''))?:'Sin ubicación cargada')?></div><div><b>Equipo asignado</b><br><?=me($it['team_names']?:'—')?></div><div><b>Arquitecto / constructora</b><br><?=me($it['partner_name']?:'—')?></div></div><?php if(!empty($it['notes'])):?><div style="padding:12px;border-left:4px solid var(--o);background:#fff8f2;border-radius:8px"><b>Indicaciones</b><br><?=nl2br(me($it['notes']))?></div><?php endif;?><div class="actions"><a class="btn" href="?a=technical_project&id=<?=$it['project_id']?>">Ver proyecto y equipamiento</a></div></article><?php endforeach;endif;?><?php if($next):?><section class="upcoming"><h2>Próximos trabajos</h2><?php foreach($next as $n):?><div class="upcoming-row"><div><b><?=me(date('d/m',strtotime($n['work_date'])))?></b><br><span class="muted"><?=me($n['start_time']?substr($n['start_time'],0,5):'')?></span></div><div><b><?=me($n['project_number'].' · '.$n['project_name'])?></b><br><span class="muted"><?=me($n['title'])?></span></div><a class="btn light" href="?a=my_day&date=<?=me($n['work_date'])?>">Ver día</a></div><?php endforeach;?></section><?php endif;?></main></body></html>